<include file="Publics:header"/>	<div class="mainbox">		<div id="nav" class="mainnav_title">			<ul>				<a href="{pigcms{:U('Library/shop_goods_seckill_pop',array('goods_type'=>'shop'))}"  <if condition="empty($goods_type) OR $goods_type eq 'shop'"> class="on" </if> > 外 卖 </a> |                 <a href="{pigcms{:U('Library/shop_goods_seckill_pop',array('goods_type'=>'mall'))}"  <if condition="$goods_type eq 'mall'"> class="on" </if> > 商 城 </a> |                 <a href="{pigcms{:U('Library/shop_goods_seckill_pop',array('goods_type'=>'village_group'))}" <if condition="$goods_type eq 'village_group'"> class="on"  </if> >社区团购</a>			</ul>		</div>		<form name="myform" id="myform" action="{pigcms{:U('Library/shop_goods_seckill_pop')}" method="get">            <div>		    <input type="hidden" name="g" value="House"/>            <input type="hidden" name="c" value="Library"/>            <input type="hidden" name="a" value="shop_goods_seckill_pop"/>            <input type="hidden" name="goods_type" id="goods_type" value="{pigcms{$goods_type}"/>            <input type="hidden" name="frame_show" value="true"/>            <input type="hidden" name="frame" value="1"/>            商品名称：<input value="{pigcms{$_GET['goods_name']}" class="col-sm-2" name="goods_name" id="goods_name" type="text" style="float: none;height:35px;margin:10px;width: 180px;"  placeholder="请输入商品名称" autocomplete="off"  />            <input style="line-height: 10px;" class="btn btn-success" type="submit" id="find_submit" value=" 搜 索 " />            <span class="form_tips"></span>         </div>			<div class="table-list">				<table width="100%" cellspacing="0">					<thead>						<tr>                            <th style="text-align:center"><input type="checkbox" class="checkbox_all" style="wdith:20px; height:20px;"></th>							<th>ID</th>							<th>商品名称</th>                            <th>原价</th>							<th>优惠价</th>							<th>所属商家/店铺</th>                            <th>活动开始时间</th>                            <th>活动截止时间</th>						</tr>					</thead>					<tbody class="tbodyContainer">						<if condition="is_array($goods_list) AND !empty($goods_list)">							<volist name="goods_list" id="vo">								<tr>                                   <td align="center"><input type="checkbox" name="selectVbox[]" class="selectVbox" style="wdith:20px; height:20px;" value="{pigcms{$vo.goods_id}" data-a_id="{pigcms{$vo.id}" data-goods_name="{pigcms{$vo.goods_name}" data-store_name="{pigcms{$vo.store_name}" data-merchant_name="{pigcms{$vo.merchant_name}" data-price="{pigcms{$vo.price}" data-discount_price="{pigcms{$vo.discount_price}" data-stock_num="{pigcms{$vo.stock_num}" data-goods_status="{pigcms{$vo.goods_status}" data-active_start_time="{pigcms{$vo.active_start_time}" data-active_end_time="{pigcms{$vo.active_end_time}" data-url="{pigcms{$vo.url}" data-image="{pigcms{$vo.image}" onclick="return Dcheckbox($(this));"></td>									<td>{pigcms{$vo.goods_id}</td>									<td><div><img src="{pigcms{$vo.image}" style="width: 82px;height: 82px;border-radius: 15px;margin-right: 5px;"><span>{pigcms{$vo.goods_name}</span></div></td>                                    <td>￥{pigcms{$vo.price}</td>                                    <td>￥{pigcms{$vo.discount_price}</td>						            <td>{pigcms{$vo.merchant_name} / {pigcms{$vo.store_name}</td>									<td>{pigcms{$vo.active_start_time}</td>                                    <td>{pigcms{$vo.active_end_time}</td>								</tr>							</volist>						<else/>							<tr>                                <td class="textcenter red"  colspan="8" >列表为空！</td>                            </tr>						</if>					</tbody>				</table>                {pigcms{$pagebar}			</div>		</form>	</div><style>    .table-list .summary {        margin: 10px 25px 5px 0 !important;        text-align: right !important;    }    .table-list .pager {        margin: 0 25px 5px 0 !important;        text-align: right !important;    }    .pager .next>a {        height: 30px;        line-height: 30px;    }    .pager .prev>a {        height: 30px;        line-height: 30px;    }</style><script type="text/javascript">$(".checkbox_all").on('click',function(){	if($(this).is(':checked')){		$("input[name='selectVbox[]']").prop("checked",true);	}else{		$("input[name='selectVbox[]']").prop("checked",false);	}});function Dcheckbox(e){	var n=0;	var len = $("input[name='selectVbox[]']").length;	for(var i=0;i<len;i++){		if($("input[name='selectVbox[]']")[i].checked){ n++; };	}	if(n==len){		$(".checkbox_all").prop("checked",true);	}else{		$(".checkbox_all").prop("checked",false);	}}</script><include file="Publics:footer"/>